def compute(vars):
    securities = vars["v1"]
    exercise_price = vars["v2"]
    value_millions = (securities * exercise_price) / 1000000
    return {
        "value": value_millions,
        "trace": {
            "securities": securities,
            "exercise_price": exercise_price,
            "value_in_millions": value_millions,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": "currency"
            }
        }
    }
